W=[
E('endogenous','英 /enˈdɒdʒənəs/；美 /enˈdɑːdʒənəs/','内生的；内源的','先给系统画一个边界，再问：东西是里面自己产生的吗？','endo- 内部 + -genous 产生的；早期植物学“内生”用法后来扩大。',G+[['endo- 内 + 希腊来源 -genous → endogenous','在内部生长或产生的']],'人体自己产生的激素可叫 endogenous hormone；模型中的 endogenous variable 是由模型内部关系决定的变量。“内部”总相对于当前系统，不是永远固定在人体里。','endogenous production；an endogenous variable。','exogenous 来自外部；同一因素在一个模型中内生，在另一个模型中可能外生。',('The study measured endogenous hormone production.','研究测量了体内自身产生激素的情况。'),('Prices are endogenous in this model.','在这个模型中，价格由模型内部关系决定。'),sources=['https://www.merriam-webster.com/dictionary/endogenous']),
E('exogenous','英 /ekˈsɒdʒənəs/；美 /ekˈsɑːdʒənəs/','外生的；外源的','改变来自边界之外，好像有人从盒子外向里面推了一下。','exo- 外部 + -genous 产生的；与 endogenous 成对。',G+[['exo- 外 + 希腊来源 -genous → exogenous','在所讨论系统之外产生或从外部引入的']],'exogenous hormone 指从体外引入的激素；exogenous shock 在经济模型里指外来的冲击。这不是“外来的基因”，也不自动表示有害。','an exogenous shock；exogenous factors。','external 只是一般“外部”；exogenous 特别强调原因、产生地或决定因素在系统外。',('The model treats the weather as an exogenous factor.','模型把天气当作外生因素。'),('The researchers distinguished endogenous from exogenous hormones.','研究人员区分了内源性激素与外源性激素。'),sources=['https://www.merriam-webster.com/dictionary/exogenous']),
E('autogenous','英 /ɔːˈtɒdʒənəs/；美 /ɔːˈtɑːdʒənəs/','自生的；自体来源的','材料或作用由自身提供，不必再从另一个个体或外部源头拿来。','auto- 自己 + -genous 产生的，可能受希腊 autogenḗs“自生”影响。',G+[['auto- 自 + -genous → autogenous','由自身产生或取自同一个体的']],'autogenous graft 是取自患者自身的移植物；autogenous pressure 是系统内物质自身产生的压力。两处都抓住“来源在自身”，但具体机制不同。','an autogenous graft；autogenous pressure。','autonomous 指自主、自治；autogenous 指自生、自体来源，不能只凭 auto- 当同义词。',('The procedure used an autogenous graft.','该操作使用了自体移植物。'),('The vessel developed autogenous pressure as it warmed.','容器内物质随升温产生了自生压力。'),sources=['https://www.merriam-webster.com/dictionary/autogenic']),
E('gonad','英 /ˈɡəʊnæd/；美 /ˈɡoʊnæd/','性腺','把它看作产生生殖细胞的器官，而不是所有生殖器官的总称。','希腊 gonḗ“生殖、种子、后代”，经新拉丁器官名 gonas，词干 gonad- 进入英语。',GO,'人体的睾丸和卵巢都属于 gonads，同时参与性激素分泌。日常俚语有时把 gonads 只用于睾丸，但生物学定义包括卵巢。','the male gonads；the female gonads；gonad development。','genitals 常指生殖器尤其外生殖器；gonads 明确是性腺，两者范围不同。',('The ovaries are the female gonads.','卵巢是女性性腺。'),('The lesson describes how gonads develop.','这堂课介绍性腺如何发育。'),sources=BIO),
E('gonadal','英 /ɡəʊˈnædəl/；美 /ɡoʊˈnædəl/','性腺的','把器官名 gonad 变成“关于这个器官”的描述。','gonad + -al。',A(GO,'英语 gonadal','关于性腺的'),'gonadal hormones 是性腺产生的激素；gonadal tissue 是性腺组织。它不泛指一切与性有关的事，也不是把 gon- 拆成“角”。','gonadal function；gonadal development；gonadal hormones。','hormonal 讲激素，更广；gonadal 指性腺，既可谈激素，也可谈器官组织。',('The study examined gonadal development in fish.','研究考察了鱼类性腺发育。'),('The report describes changes in gonadal tissue.','报告描述了性腺组织的变化。'),sources=BIO),
E('hypogonadism','英 /ˌhaɪpəʊˈɡəʊnædɪzəm/；美 /ˌhaɪpoʊˈɡoʊnædɪzəm/','性腺功能减退','“生产部门”工作不足：性腺的激素或生殖细胞生成功能低下。','hypo- 低于、功能不足 + gonad 性腺 + -ism 状态。',A(GO,'现代医学词 hypo- + gonad + -ism','性腺相关功能不足的状态'),'这个词可以涉及睾丸或卵巢，原因也可能在性腺本身或调控它的信号系统。这里学的是医学名词的含义，不能把普通疲劳或单次检测值直接等同于它。','primary hypogonadism；secondary hypogonadism。','hypo- 指不足，不是器官位置在下方；hypogonadism 也不等于某一种外观特征。',('The lecture compared primary and secondary hypogonadism.','讲座比较了原发性与继发性性腺功能减退。'),('The review discusses several causes of hypogonadism.','综述讨论了性腺功能减退的几种原因。'),sources=['https://www.ncbi.nlm.nih.gov/mesh/68007006']),
E('spermatogenesis','英 /ˌspɜːmətəˈdʒenəsɪs/；美 /ˌspɜːrmətəˈdʒenəsɪs/','精子发生','从生殖细胞前体逐步走到精子，像一条分阶段进行的细胞发育过程。','spermato- 精子，源于希腊“种子” + genesis 形成。',SP,'在人类中发生于睾丸的曲细精管，涉及细胞分裂和后续形态变化。它是整个形成过程；spermiogenesis 更具体地说精子细胞向精子的形态转变阶段。','stages of spermatogenesis；regulation of spermatogenesis。','sperm 是细胞，spermatogenesis 是形成它的过程，不是射精这一行为。',('The diagram shows the stages of spermatogenesis.','图示展示了精子发生的各个阶段。'),('The researchers studied the regulation of spermatogenesis.','研究人员研究了精子发生的调控。'),sources=BIO),
E('oogenesis','英 /ˌəʊəˈdʒenəsɪs/；美 /ˌoʊəˈdʒenəsɪs/','卵子发生；卵细胞形成','把卵细胞从前体一步步发育出来的过程。','oo- 卵，来自希腊 ōón + genesis 形成；两个 o 不是拼写错误。',OO,'oogenesis 与 spermatogenesis 都属于配子发生，但时间安排与细胞分裂产物并不完全一样。这里的 egg 是生物学卵细胞，不一定是有壳的鸡蛋。','oogenesis and spermatogenesis；stages of oogenesis。','ovulation 是排卵；oogenesis 是卵细胞的形成、发育，不能把整段过程缩成“排出来”。',('The class compared oogenesis with spermatogenesis.','班上比较了卵子发生与精子发生。'),('The chart summarizes the stages of oogenesis.','图表概述了卵子发生的各个阶段。'),sources=BIO),
E('gametogenesis','/ɡəˌmiːtəˈdʒenəsɪs/','配子发生','先造出可以参与受精的生殖细胞，才谈这些细胞如何结合。','gameto- 配子，远源联系希腊 gámos“婚配” + genesis 产生。',G+[['现代生物学 gamete“配子” + genesis → gametogenesis','精子、卵细胞等配子的形成过程']],'在人类语境中，spermatogenesis 和 oogenesis 是 gametogenesis 的两条具体过程。这个总称不等于受精，也不应把所有植物、动物的生命周期细节视为完全一致。','gametogenesis in animals；normal gametogenesis。','fertilization 是配子结合；gametogenesis 是先把配子形成出来。',('Gametogenesis produces the cells needed for sexual reproduction.','配子发生形成有性生殖所需的细胞。'),('The textbook explains gametogenesis before fertilization.','教材先讲配子发生，再讲受精。'),sources=BIO),
E('cytogenetic','/ˌsaɪtəʊdʒəˈnetɪk/','细胞遗传学的','把遗传问题放到细胞里，特别看染色体的数目和结构。','cyto- 细胞 + genetic 遗传相关的；属于现代国际科学构词。',G+[['现代科学词 cyto- + genetic → cytogenetic','从细胞、染色体层面研究遗传的']],'cytogenetic analysis 常观察染色体是否多、少或有结构重排。它不是泛指所有基因检测；有些很小的序列变化需要另外的方法研究。','cytogenetic analysis；cytogenetic abnormalities。','cytological 关注细胞的一般结构；cytogenetic 特别把细胞与遗传、染色体联系起来。',('Cytogenetic analysis revealed a chromosomal rearrangement.','细胞遗传学分析发现了染色体重排。'),('The laboratory specializes in cytogenetic testing.','这个实验室专门从事细胞遗传学检测。'),sources=['https://www.cancer.gov/publications/dictionaries/cancer-terms/def/cytogenetic-analysis','https://www.merriam-webster.com/dictionary/cytogenetic']),
E('erogenous','英 /ɪˈrɒdʒənəs/；美 /ɪˈrɑːdʒənəs/','可引起性兴奋的；性感觉敏感的','在身体或心理语境里，指能引出性兴奋的敏感性。','ero- 由希腊 érōs“爱欲”而来 + -genous 产生的。',G+[['希腊 érōs + 英语 -genous → erogenous','能引起性兴奋的']],'最常见搭配是 erogenous zone，指与性兴奋相关的敏感区域。这是生理、心理描述，具体敏感性因人而异，并不是“促进基因产生”。','an erogenous zone；erogenous sensitivity。','erotic 常指带情色或唤起性欲的表达；erogenous 常落在身体区域的敏感性。',('The textbook explains the term erogenous zone.','教材解释了“性敏感区”这个术语。'),('Erogenous sensitivity varies between individuals.','性敏感程度因人而异。'),sources=['https://www.merriam-webster.com/dictionary/erogenous']),
E('genophobia','参考读法 /ˌdʒenəˈfəʊbiə/','对性行为的恐惧','这里 geno- 沿着生殖、性关系这条支线走，不是“害怕基因”。','geno- 生殖相关 + -phobia 恐惧。',G+[['现代组合词 geno- + -phobia → genophobia','对性行为或性关系的恐惧']],'这是较少见的心理描述词，不宜把普通害羞、不想发生性关系或个人选择都贴上这个标签。读文章时，先确认作者说的是恐惧，而不是单纯兴趣低。','fear described as genophobia；discuss genophobia。','gene phobia 的字面联想会误导；本词通常说对性行为的恐惧，不是遗传学研究。',('The article discusses genophobia as a fear of sexual intercourse.','文章把 genophobia 作为对性交的恐惧来讨论。'),('The author distinguishes genophobia from a lack of sexual interest.','作者区分了对性行为的恐惧与缺乏性兴趣。')),
E('biogenesis','/ˌbaɪəʊˈdʒenəsɪs/','生源论；生物体内结构或物质的生成','一个用法问“生命从哪里来”，另一个用法问“细胞里的东西怎么造出来”。','bio- 生命 + genesis 产生；19世纪生源论争论中形成的科学术语。',G+[['现代科学词 bio- + genesis → biogenesis','已有生命产生生命；后也用于细胞结构、物质的生成']],'历史生源论语境强调生命来自已有生命，反对日常条件下腐物凭空生虫等自然发生观。现代 mitochondrial biogenesis 则说线粒体的生成、增生，不是在讨论地球最初生命。','mitochondrial biogenesis；ribosome biogenesis。','abiogenesis 在现代起源研究中讨论非生命到生命的早期过程；不要与旧式“肉腐后凭空长虫”的说法混为一谈。',('The lecture reviewed the historical debate about biogenesis.','讲座回顾了有关生源论的历史争论。'),('The study examined mitochondrial biogenesis in muscle cells.','研究考察了肌肉细胞中的线粒体生成。'),sources=['https://www.merriam-webster.com/dictionary/biogenesis']),
E('epigenesis','/ˌepɪˈdʒenəsɪs/','后成；后成论；后生矿物变化','结构是在发育中一步步长出来的，不是把一个早已备好的微缩成品直接放大。','epi- 随后、加在其上 + genesis 产生；经新拉丁学术词 epigenesis 进入英语。',G+[['新拉丁 epi- + genesis → epigenesis','逐步形成的发育观'],['英语 epigenesis','胚胎后成；地质中也用于形成后的矿物变化']],'发育史上的 epigenesis 与 preformation“预成论”相对。地质中的同形词说岩石形成后受外来因素影响而改变矿物特征，抓住“后来发生”，但要换语境。','epigenesis and preformation；mineral epigenesis。','epigenetics 是现代表观遗传学，虽有词史联系，却不是 epigenesis 的简单复数。',('The historian contrasted epigenesis with preformation.','历史学家对比了后成论与预成论。'),('The chapter traces the development of the idea of epigenesis.','这一章追溯了后成思想的发展。'),sources=['https://www.merriam-webster.com/dictionary/epigenesis']),
E('anagenesis','/ˌænəˈdʒenəsɪs/','直系演化；不分支的谱系演变','想象一条线随时间变样，旧类型逐渐被新类型替代，线本身没有分成两支。','ana- 向前、向上等历史义 + genesis 产生，构成演化学术语。',G+[['现代科学词 ana- + genesis → anagenesis','同一谱系中的演变，常指不分支的类型替代']],'对比图中 anagenesis 像一根连续变化的枝，cladogenesis 像枝条分叉。不要把 ana- 的“向上”理解成生物必然越来越高级。','anagenesis and cladogenesis；evidence of anagenesis。','普通 evolution 范围更广；anagenesis 特别关注一条谱系内部的改变。',('The diagram illustrates anagenesis without branching.','图示展示了不发生分支的直系演化。'),('The fossil sequence was interpreted as evidence of anagenesis.','这组化石序列被解释为直系演化的证据。'),sources=['https://www.merriam-webster.com/dictionary/anagenesis']),
E('autogenesis','参考读法 /ˌɔːtəʊˈdʒenəsɪs/','自然发生；由内在因素主导的演化观（历史术语）','字面是“自己生出来”；旧理论借它描述生命自发出现或演化自带方向。','auto- 自己 + genesis 产生，经新拉丁学术构词。',G+[['新拉丁 aut- + genesis → 英语 autogenesis','自发生成；历史上也指由内在因素引导的演化观']],'这个词多在科学史或特定理论里出现。名称不等于理论已经被证实；现代讨论生命起源通常使用更明确的术语和具体机制。','the theory of autogenesis；historical accounts of autogenesis。','autogenous 仍常用作“自体、自生”的专业形容词，不能据此认定 autogenesis 的旧理论都成立。',('The book examines nineteenth-century ideas about autogenesis.','这本书考察了十九世纪有关自然发生的观念。'),('The author treated autogenesis as a historical theory.','作者把 autogenesis 作为一种历史理论讨论。'),sources=['https://www.merriam-webster.com/dictionary/autogenesis']),
E('endogen','/ˈendədʒɪn/','内生植物（旧植物学名称）','老植物学家把某些茎的生长方式理解成“从里面添东西”，据此给植物分类。','endo- 内部 + -gen 产生，经法语 endogène 进入英语。',G+[['法语 endogène → 英语 endogen','按所谓内生方式分类的植物名称']],'旧文献中的 endogen 常用于大多数单子叶植物。它属于旧分类语言，不能把它当作现代植物系统分类的通用正式层级。','an endogen；endogens and exogens（旧分类）。','endogenous 是广泛使用的“内生的”；endogen 是较窄、较旧的植物名词。',('The old botanical text classified the palm as an endogen.','这本旧植物学书把棕榈归为内生植物。'),('The glossary explains the historical term endogen.','词汇表解释了 endogen 这个历史术语。'),sources=['https://www.merriam-webster.com/dictionary/endogen']),
E('epigene','/ˈepɪdʒiːn/','表成的；地表附近形成的','矿物作用的故事发生在地表或浅处，而不是很深的地下。','经法语 épigène，源于希腊 epigenḗs“后来长成的”，联系 epi- + gígnesthai。',G+[['希腊 epigenḗs → 法语 épigène → 英语 epigene','后形成；地质中指地表或近地表形成']],'地质学的 epigene processes 是表成作用；矿物学旧义也用于不属于现有物质固有晶形的外来形态。看到 gene 结尾，别以为在讲 DNA。','epigene processes；epigene minerals。','hypogene 强调地下深处；epigene 强调地表附近，区分的是形成位置和作用环境。',('The paper describes epigene alteration of the rock.','论文描述了岩石的表成蚀变。'),('The lecturer contrasted epigene and hypogene processes.','讲师对比了表成作用与深成作用。'),sources=['https://www.merriam-webster.com/dictionary/epigene']),
E('epigone','英 /ˈepɪɡəʊn/；美 /ˈepɪɡoʊn/','逊于前人的追随者；缺乏原创性的模仿者','后来者沿着大师留下的脚印走，却没走出自己的路。','希腊 epi- 随后 + -gonos 出生的，epígonos“后代”；近代欧洲语言转借的路径在词源书中有德语、法语等记载。',G+[['希腊 epígonos → 拉丁 epigonus；近代德语、法语相关借词','后来出生者、继承者'],['英语 epigone','较缺乏原创性的追随者']],'在艺术、文学评论里，说某人 merely an epigone 通常是批评他只是模仿前人。它不只是中性的 student，也不必真有血缘关系。','an epigone of；mere epigones。','disciple 可表示有价值的传承；epigone 常带“作品或思想不及前辈”的贬意。',('Critics dismissed him as an epigone of the older poet.','评论家把他贬为那位老诗人的拙劣追随者。'),('She wanted to create her own style, not remain an epigone.','她想创造自己的风格，不愿一直做缺乏原创性的模仿者。'),sources=['https://www.etymonline.com/word/epigone','https://art19.com/shows/merriam-websters-word-of-the-day/episodes/25631b24-346e-49c0-9e3f-ee74fba99d3d']),
E('homogenesis','/ˌhəʊməˈdʒenəsɪs/','同型生殖（旧生物学用语）','后代按与亲代相似的生活形式发展，不在世代间换成完全不同的形态。','homo- 相同 + genesis 产生，经新拉丁学术构词。',G+[['新拉丁 hom- + genesis → 英语 homogenesis','产生与亲代相似后代的生殖方式']],'这个旧术语用于描述世代形态的相似，不是说亲子每个基因都一样。阅读现代生物学时，应以作者对生活史和繁殖方式的具体定义为准。','homogenesis and heterogenesis（历史分类）。','homogeneous 是均一的；homogenesis 是繁殖、世代关系术语，不能把 -genesis 当形容词尾。',('The old textbook contrasted homogenesis with heterogenesis.','旧教材对比了同型生殖与异型生殖。'),('The author used homogenesis for reproduction with similar successive generations.','作者用 homogenesis 表示相继世代形态相似的生殖方式。'),sources=['https://www.merriam-webster.com/dictionary/homogenesis']),
E('homogenetic','参考读法 /ˌhəʊməʊdʒəˈnetɪk/','同源的；具有共同起源的（少见生物学用语）','两个结构相像，是因为它们从共同祖先那里传下来，而不只是偶然长得像。','homo- 相同 + genetic 起源相关的；此处 genetic 保留“起源”这层旧义。',G+[['英语 hom- + genetic → homogenetic','具有相同起源、同源关系的']],'旧比较生物学材料用它讨论共同来源的结构。它不是断言两个生物的整个基因组完全相同，也不宜把它当日常“均匀”的首选词。','homogenetic similarities；homogenetic structures（少见）。','homogeneous 常讲组成均一；homogenetic 在这里讲起源关系，问题不同。',('The author interpreted the structures as homogenetic.','作者把这些结构解释为同源的。'),('The historical paper distinguishes homogenetic similarity from mere resemblance.','这篇历史论文区分了同源相似与单纯外形相似。'),sources=['https://www.merriam-webster.com/dictionary/homogenetic','https://en.wiktionary.org/wiki/homogenetic#English']),
E('hypogene','/ˈhaɪpədʒiːn/','深成的；地下形成的','把形成地点往地下放，常想到深部流体和地下矿物形成。','hypo- 下方 + 希腊 -genēs 产生的。',G+[['现代地质词 hypo- + -genēs → hypogene','地表以下较深处形成的']],'hypogene minerals 强调矿物的地下成因，常与近地表后期变化作对比。并不是说这种物质“基因少”，也不保证所有用法都限定同一深度。','hypogene mineralization；hypogene deposits。','epigene 指地表附近的形成；hypogene 关注地下来源。',('The geologist identified hypogene mineralization in the core.','地质学家在岩芯中辨认出了深成矿化。'),('The report separates hypogene minerals from later alteration products.','报告把深成矿物与较晚的蚀变产物区分开。'),sources=['https://www.merriam-webster.com/dictionary/hypogene']),
E('hypogenic','参考读法 /ˌhaɪpəˈdʒenɪk/','深成作用的；源于地下作用的','描述过程来自地下，而不是从地面直接开始。','hypogene + -ic。',G+[['hypo- 下 + -genēs 产生 → hypogene','地下形成的'],['英语 hypogene + -ic → hypogenic','有关地下形成或结晶作用的']],'hypogenic action 是地质形成、结晶等地下作用。它与 hypogene 很接近，常在技术文献里修饰过程；不要与 hypoallergenic“低致敏”混淆。','hypogenic processes；hypogenic crystallization。','hypogenic 不等于“不够有创造力”；这里 gen- 是地质的形成，hypo- 是位置在下。',('The study examines hypogenic processes in the region.','研究考察了该地区的深成作用。'),('The mineral texture suggests hypogenic crystallization.','矿物的组织特征提示其形成于深成结晶作用。'),sources=['https://www.merriam-webster.com/dictionary/hypogenic']),
E('hypogenesis','/ˌhaɪpəˈdʒenəsɪs/','发育不全；无世代交替的直接发育（专业旧义）','在常见医学义里，某个结构的形成没有达到通常的程度。','hypo- 不足 + genesis 形成；生物学另有直接发育的专业旧义。',G+[['现代学术词 hypo- + genesis → hypogenesis','发育不足；另有无世代交替的直接发育义']],'医学材料中的 hypogenesis of an organ 是器官发育不足，不是器官后来被磨小。若旧生物学文本谈世代交替，就要换到第二个义项，不能只按“发育差”硬译。','hypogenesis of an organ；congenital hypogenesis。','agenesis 是未形成或缺如；hypogenesis 指形成不足，通常不是完全没有。',('The report describes hypogenesis of part of the organ.','报告描述了该器官某一部分的发育不全。'),('The glossary distinguishes hypogenesis from agenesis.','词汇表区分了发育不全与未形成。'),sources=['https://www.merriam-webster.com/medical/hypogenesis']),
E('hypogenous','英 /haɪˈpɒdʒɪnəs/；美 /haɪˈpɑːdʒənəs/','生于下表面的（植物学）','翻到叶片背面，某些孢子结构或真菌正长在那里。','hypo- 下方 + -genous 生长、产生的。',G+[['植物学 hypo- + -genous → hypogenous','长在某个表面下侧的']],'这里“下”是叶等结构的下表面，不一定是土壤下面。这个少见词把位置和生长联系起来，比简单 under 多了“产生于此”的意思。','hypogenous fungi；hypogenous spores（植物学）。','hypogene 常是地质“地下形成”；hypogenous 在此是植物学“下表面生长”，应用场景不同。',('The botanist noted hypogenous growth on the leaf.','植物学家记录了叶片下表面的生长物。'),('The description refers to hypogenous spores.','这段描述说的是生于下表面的孢子。'),sources=['https://www.collinsdictionary.com/us/dictionary/english/hypogenous']),
E('paragenesis','/ˌpærəˈdʒenəsɪs/','矿物共生关系；矿物生成序列','把一块矿石当作现场：哪些矿物一起形成，谁先谁后，彼此怎样影响。','para- 旁边、共同 + genesis 形成，经新拉丁科学词进入英语。',G+[['新拉丁 para- + genesis → paragenesis','矿物共同形成及其先后关系']],'研究 paragenesis 不只是列矿物名字，还要利用交切、包裹等关系推断形成次序。这里“共生”不保证所有矿物在同一瞬间出现。','mineral paragenesis；the paragenesis of an ore deposit。','mineral composition 只讲有哪些成分；paragenesis 更关心形成关联和时间次序。',('The geologist reconstructed the paragenesis of the ore minerals.','地质学家重建了矿石矿物的生成序列。'),('The report discusses the paragenesis of quartz and sulphides.','报告讨论了石英与硫化物的共生形成关系。'),sources=['https://www.merriam-webster.com/dictionary/paragenesis','https://pubs.usgs.gov/gf/038/text.pdf']),
E('polygenous','/pəˈlɪdʒənəs/','由多种成分或类型组成的；多源的','拼成整体的材料不止一种，来源也可能不止一条。','poly- 多 + -genous 种类、产生相关的。',G+[['英语 poly- + -genous → polygenous','包含多种类型或成分的']],'这是较少见的学术形容词，可表示多类组成或多重来源。现代一般表达常用 heterogeneous、diverse 或 of multiple origins 更清楚。','a polygenous collection；polygenous origins（少见）。','polygenic 通常是“多基因的”；polygenous 不应自动翻译成多个基因共同控制。',('The author described the collection as polygenous.','作者把这一合集描述为由多种类型组成。'),('The glossary explains polygenous as containing several kinds of elements.','词汇表把 polygenous 解释为包含几种不同成分的。'),sources=['https://www.merriam-webster.com/dictionary/polygenous']),
E('progenesis','/ˌprəʊˈdʒenəsɪs/','生殖早熟；早熟生殖','身体仍保留较幼的形态，生殖成熟这一步却提前到了。','pro- 提前 + genesis 产生，用于发育与生殖时序。',G+[['现代生物学 pro- + genesis → progenesis','生殖成熟提前，使个体在较幼形态下繁殖']],'演化发育学里，progenesis 可使成年个体保留祖先幼体的一些特征。它与 neoteny 都可能关联幼态延续，但前者强调生殖时序提前，后者强调身体发育变慢。','progenesis and neoteny；progenesis in a lineage。','不是所有幼态动物都能仅凭外形判为 progenesis；必须看发育时序证据。',('The study proposed progenesis as an explanation for the retained juvenile traits.','研究提出，生殖早熟可能解释这些保留下来的幼体特征。'),('The lecture distinguished progenesis from neoteny.','讲座区分了生殖早熟与幼态持续。'),sources=['https://www.merriam-webster.com/medical/progenesis','https://pmc.ncbi.nlm.nih.gov/articles/PMC8888124/']),
]
